function Get-AI5GeminiApiCredentialStatus {Get-AI5ApiNodeStatus 'gemini_api'}
function New-AI5GeminiApiRequest {param($Task,[string]$Model='gemini');if(!$Task.TASK_ID-or!$Task.CORRELATION_ID){throw 'zero_task_identity_required'};[ordered]@{provider='google';node='gemini_api';model=$Model;task_id=$Task.TASK_ID;correlation_id=$Task.CORRELATION_ID;purpose=$Task.PURPOSE;canonical_repo=$Task.CANONICAL_REPO;canonical_branch=$Task.CANONICAL_BRANCH;allowed_actions=@($Task.ALLOWED_ACTIONS);prohibited_actions=@($Task.PROHIBITED_ACTIONS);expected_result=$Task.EXPECTED_RESULT}}
function Invoke-AI5GeminiApiAdapter {param($Task,[scriptblock]$Transport=$null,[string]$ApiKey='',[string]$Model='gemini-3.5-flash')
  if(!$ApiKey){$ApiKey=[Environment]::GetEnvironmentVariable('GOOGLE_API_KEY')};if(!$ApiKey){$ApiKey=[Environment]::GetEnvironmentVariable('GEMINI_API_KEY')}
  if(!$ApiKey-and!$Transport){return [ordered]@{TASK_ID=$Task.TASK_ID;CORRELATION_ID=$Task.CORRELATION_ID;AGENT='gemini_api';STATUS='WAITING_OWNER_AUTH';SUMMARY='Gemini API credential is not configured';EVIDENCE=@();ATTEMPT=1;FINISHED_AT=[DateTime]::UtcNow.ToString('o')}}
  $request=New-AI5GeminiApiRequest $Task $Model;$uri="https://generativelanguage.googleapis.com/v1beta/models/$Model`:generateContent";$headers=@{'x-goog-api-key'=$ApiKey;'content-type'='application/json'};$payload=[ordered]@{contents=@([ordered]@{role='user';parts=@([ordered]@{text=($request|ConvertTo-Json -Depth 12)})})}
  try{$response=if($Transport){&$Transport $uri $headers $payload}else{Invoke-RestMethod -Method Post -Uri $uri -Headers $headers -Body ($payload|ConvertTo-Json -Depth 12) -TimeoutSec 120};$text=[string]$response.candidates[0].content.parts[0].text;if(!$text){throw 'empty_api_result'};[ordered]@{TASK_ID=$Task.TASK_ID;CORRELATION_ID=$Task.CORRELATION_ID;AGENT='gemini_api';STATUS='PASS';SUMMARY=$text;EVIDENCE=@('gemini_generate_content_api');ATTEMPT=1;FINISHED_AT=[DateTime]::UtcNow.ToString('o')}}catch{[ordered]@{TASK_ID=$Task.TASK_ID;CORRELATION_ID=$Task.CORRELATION_ID;AGENT='gemini_api';STATUS='FAIL';SUMMARY='Gemini API request failed';EVIDENCE=@('transport_failure_redacted');ATTEMPT=1;FINISHED_AT=[DateTime]::UtcNow.ToString('o')}}
}
